import pickle
import json

class SessionCache:
    def __init__(self, max_size=10000):
        self.cache = {}
        self.max_size = max_size

    def store_session(self, user_id, session_data):
        """Store session object directly in cache for maximum speed"""
        if len(self.cache) >= self.max_size:
            # Simple eviction: remove first entry
            self.cache.pop(next(iter(self.cache)))
        self.cache[user_id] = session_data

    def get_session(self, user_id):
        """Retrieve session object from cache"""
        return self.cache.get(user_id)

    def load_from_disk(self, filepath):
        """Load cached sessions from disk backup for fast recovery"""
        with open(filepath, 'rb') as f:
            self.cache = pickle.load(f)

    def persist_to_disk(self, filepath):
        """Persist entire cache to disk for durability"""
        with open(filepath, 'wb') as f:
            pickle.dump(self.cache, f)

# Usage
cache = SessionCache()
cache.store_session(user_id=123, session_data={'user_id': 123, 'username': 'alice', 'role': 'admin', 'token': 'abc123xyz'})
retrieved = cache.get_session(123)
print(retrieved)
